<?php
class Report extends Model {
  static function adminDashboard() { return self::one("SELECT (SELECT COUNT(*) FROM landlord) landlords,(SELECT COUNT(*) FROM tenant) tenants,(SELECT COUNT(*) FROM apartment_building) buildings,(SELECT COUNT(*) FROM unit) units,(SELECT COUNT(*) FROM unit WHERE availability_status='Available') available,(SELECT COUNT(*) FROM unit WHERE availability_status='Occupied') occupied,(SELECT COUNT(*) FROM unit WHERE availability_status='Unavailable') maintenance,(SELECT COUNT(*) FROM landlord WHERE verification_status='Pending') pending_registrations,(SELECT COUNT(*) FROM booking) bookings,(SELECT COALESCE(SUM(amount_paid),0) FROM payment WHERE payment_status='Verified') collected,(SELECT COALESCE(SUM(balance),0) FROM rental_bill)+(SELECT COALESCE(SUM(balance),0) FROM utility_bill) outstanding"); }
  static function admin() { return self::rows("SELECT 'Users' report,COUNT(*) total FROM users UNION ALL SELECT 'Landlords pending',COUNT(*) FROM landlord WHERE verification_status='Pending' UNION ALL SELECT 'Buildings',COUNT(*) FROM apartment_building UNION ALL SELECT 'Units occupied',COUNT(*) FROM unit WHERE availability_status='Occupied' UNION ALL SELECT 'Bookings pending',COUNT(*) FROM booking WHERE booking_status='Pending' UNION ALL SELECT 'Active rentals',COUNT(*) FROM rental WHERE rental_status='Active' UNION ALL SELECT 'Rental collected (PHP)',COALESCE(SUM(amount_paid),0) FROM payment WHERE payment_status='Verified' AND bill_category='Rental' UNION ALL SELECT 'Electricity collected (PHP)',COALESCE(SUM(amount_paid),0) FROM payment WHERE payment_status='Verified' AND bill_category='Electricity' UNION ALL SELECT 'Water collected (PHP)',COALESCE(SUM(amount_paid),0) FROM payment WHERE payment_status='Verified' AND bill_category='Water'"); }
  static function landlord($l) { $c = fn($cat) => "SELECT '$cat collected' report,COALESCE(SUM(p.amount_paid),0) total FROM payment p JOIN unit n USING(unit_id) JOIN apartment_building ab USING(building_id) WHERE ab.landlord_id=? AND p.payment_status='Verified' AND p.bill_category='$cat'";
    return self::rows($c('Rental').' UNION ALL '.$c('Electricity').' UNION ALL '.$c('Water')." UNION ALL SELECT 'Units occupied',COUNT(*) FROM unit n JOIN apartment_building ab USING(building_id) WHERE ab.landlord_id=? AND n.availability_status='Occupied' UNION ALL SELECT 'Units available',COUNT(*) FROM unit n JOIN apartment_building ab USING(building_id) WHERE ab.landlord_id=? AND n.availability_status='Available' UNION ALL SELECT 'Overdue bills',(SELECT COUNT(*) FROM rental_bill rb JOIN unit n USING(unit_id) JOIN apartment_building ab USING(building_id) WHERE ab.landlord_id=? AND rb.status='Overdue')+(SELECT COUNT(*) FROM utility_bill ub JOIN unit n USING(unit_id) JOIN apartment_building ab USING(building_id) WHERE ab.landlord_id=? AND ub.status='Overdue')", array_fill(0, 7, $l)); }
}
